const wh = $('New Project Webhook').first().json || {};
const headers = wh.headers || {};
const sourceIp = headers['x-real-ip']
  || (headers['x-forwarded-for'] || '').toString().split(',')[0].trim()
  || 'unknown';
const out = {
  source_ip: sourceIp,
  user_agent: headers['user-agent'] || 'unknown',
  endpoint: '/webhook/new-project',
  max_per_minute: 30,
  agent_name: 'init_new_project'
};
return [{ json: out }];

const item = $input.first().json;
const projectId = $('Create Project').first()?.json?.id || null;
const projectName = $('Create Project').first()?.json?.name || ($('Validate Input').first()?.json?.project_name || 'unknown');
let failedSubWf = 'unknown';
if ($('Webhook Security')?.isExecuted && !$('Restore Webhook Payload')?.isExecuted) failedSubWf = 'util_webhook_security';
else if ($('Call \'util_file_organizer\'')?.isExecuted && !$('Log Project Creation')?.isExecuted) failedSubWf = 'util_file_organizer';
let errorMessage = 'Unknown error';
let errorStack = '';
if (typeof item.error === 'string') errorMessage = item.error.substring(0, 500);
else if (item.error && typeof item.error === 'object') {
  errorMessage = (item.error.message || item.error.description || JSON.stringify(item.error)).toString().substring(0, 500);
  errorStack = (item.error.stack || '').toString().substring(0, 4000);
}
return [{json:{project_id: projectId, project_name: projectName, failed_subworkflow: failedSubWf, error_message: errorMessage, error_stack: errorStack, execution_id: $execution?.id || null, timestamp: new Date().toISOString()}}];
